INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_0','How long does delivery take?','Automatic products are delivered instantly. Manual products are delivered by our team, normally within the time shown on the product.',0);
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_1','How do I add funds?','Open Wallet, choose Add Funds, pay by Bank Transfer, Easypaisa or JazzCash, and submit the transaction ID with a screenshot. Funds appear after an admin verifies the payment.',1);
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_2','Can I get a refund?','Only products marked refund-eligible can be refunded, according to the Refund Policy. Open a support ticket from your order.',2);
